insert into public.recipes
  (name, category, kind, recipe, ingredients, calories, protein_g, fat_g, carbs_g, fiber_g, diet, allergens, cuisine, cook_minutes, budget)
values
  ('Вівсянка з ягодами', 'сніданок', 'основна страва', 'Зваріть пластівці в молоці 5 хвилин. Зверху викладіть ягоди й полийте медом.', '[{"name": "Вівсяні пластівці", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Ягоди", "amount": "80 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 320, 11.5, 7.5, 50.8, 7.4, 'vegetarian', array['berries', 'gluten', 'honey', 'lactose']::text[], null, 10, 'low'),
  ('Вівсянка з яблуком і корицею', 'сніданок', 'основна страва', 'Зваріть пластівці в молоці. Додайте нарізане яблуко та корицю й прогрійте ще 2 хвилини.', '[{"name": "Вівсяні пластівці", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Яблуко", "amount": "1 шт"}, {"name": "Спеції", "amount": "0.5 ч. л."}]'::jsonb, 344, 11.4, 7.6, 58.5, 8.8, 'vegetarian', array['gluten', 'lactose']::text[], null, 10, 'low'),
  ('Вівсянка з арахісовою пастою', 'сніданок', 'основна страва', 'Зваріть пластівці в молоці. Додайте арахісову пасту й нарізаний банан.', '[{"name": "Вівсяні пластівці", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Банан", "amount": "0.5 шт"}, {"name": "Арахісова паста", "amount": "1 ст. л."}]'::jsonb, 405, 15.3, 14.9, 53.1, 7.5, 'vegetarian', array['gluten', 'lactose', 'peanuts']::text[], null, 10, 'low'),
  ('Нічна вівсянка з чіа', 'сніданок', 'основна страва', 'Змішайте пластівці, йогурт і чіа в банці. Залиште в холодильнику на ніч. Вранці додайте ягоди й мед.', '[{"name": "Вівсяні пластівці", "amount": "40 г"}, {"name": "Йогурт натуральний", "amount": "120 г"}, {"name": "Насіння чіа", "amount": "10 г"}, {"name": "Ягоди", "amount": "60 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 317, 12.2, 9.7, 45.3, 9.2, 'vegetarian', array['berries', 'gluten', 'honey', 'lactose']::text[], null, 5, 'low'),
  ('Пшоняна каша з гарбузом', 'сніданок', 'основна страва', 'Нарізаний гарбуз тушкуйте 10 хвилин. Додайте промите пшоно й молоко та варіть до готовності.', '[{"name": "Пшоно", "amount": "60 г"}, {"name": "Гарбуз", "amount": "150 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 363, 12.5, 10.3, 58.2, 5.8, 'vegetarian', array['lactose']::text[], 'ukrainian', 30, 'low'),
  ('Манна каша з полуницею', 'сніданок', 'основна страва', 'Вмішайте манку в гаряче молоко й варіть 3 хвилини. Додайте цукор, масло та полуницю.', '[{"name": "Манна крупа", "amount": "40 г"}, {"name": "Молоко", "amount": "200 мл"}, {"name": "Цукор", "amount": "1 ч. л."}, {"name": "Вершкове масло", "amount": "1 ч. л."}, {"name": "Полуниця", "amount": "60 г"}]'::jsonb, 314, 10.3, 9.6, 47.0, 2.8, 'vegetarian', array['berries', 'gluten', 'lactose']::text[], null, 15, 'low'),
  ('Кукурудзяна каша з сиром', 'сніданок', 'основна страва', 'Всипте крупу в окріп і варіть 15 хвилин, помішуючи. Додайте масло та тертий сир.', '[{"name": "Кукурудзяна крупа", "amount": "60 г"}, {"name": "Вода", "amount": "200 мл"}, {"name": "Твердий сир", "amount": "30 г"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 351, 12.3, 13.1, 45.6, 4.2, 'vegetarian', array['corn', 'lactose']::text[], 'italian', 20, 'low'),
  ('Гречана каша з яйцем і зеленню', 'сніданок', 'основна страва', 'Відваріть гречку до готовності. Зваріть яйце. Подавайте разом із маслом і зеленню.', '[{"name": "Гречка", "amount": "60 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Зелень (кріп, петрушка)", "amount": "10 г"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 322, 14.8, 11.3, 38.2, 6.3, 'vegetarian', array['eggs', 'lactose']::text[], 'ukrainian', 25, 'low'),
  ('Рисова каша з гарбузом', 'сніданок', 'основна страва', 'Зваріть рис із натертим гарбузом у молоці до густоти. Додайте мед.', '[{"name": "Рис", "amount": "50 г"}, {"name": "Гарбуз", "amount": "100 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 295, 8.9, 4.2, 57.8, 1.2, 'vegetarian', array['honey', 'lactose']::text[], null, 30, 'low'),
  ('Яєчня з помідорами', 'сніданок', 'основна страва', 'Обсмажте нарізаний помідор 2 хвилини. Вбийте яйця й готуйте під кришкою 4 хвилини. Посипте зеленню.', '[{"name": "Яйце", "amount": "2 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}]'::jsonb, 222, 14.9, 15.7, 5.0, 1.4, 'vegetarian', array['eggs', 'tomatoes']::text[], null, 10, 'low'),
  ('Омлет зі шпинатом і сиром', 'сніданок', 'основна страва', 'Прогрійте шпинат на олії. Залийте збитими яйцями, посипте сиром і готуйте під кришкою 5 хвилин.', '[{"name": "Яйце", "amount": "3 шт"}, {"name": "Шпинат", "amount": "50 г"}, {"name": "Твердий сир", "amount": "20 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 362, 27.2, 26.3, 3.0, 1.1, 'vegetarian', array['eggs', 'lactose']::text[], null, 10, 'low'),
  ('Шакшука', 'сніданок', 'основна страва', 'Обсмажте цибулю з перцем і часником. Додайте томати й тушкуйте 10 хвилин. Вбийте яйця й готуйте під кришкою 5 хвилин.', '[{"name": "Яйце", "amount": "2 шт"}, {"name": "Томати в соку", "amount": "200 г"}, {"name": "Солодкий перець", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 288, 17.6, 16.0, 19.3, 5.0, 'vegetarian', array['eggs', 'tomatoes']::text[], 'mediterranean', 25, 'low'),
  ('Тост з яйцем пашот і шпинатом', 'сніданок', 'основна страва', 'Підсушіть хліб і намастіть маслом. Зваріть яйця пашот у киплячій воді 3 хвилини. Викладіть на хліб зі шпинатом.', '[{"name": "Яйце", "amount": "2 шт"}, {"name": "Цільнозерновий хліб", "amount": "2 скибки"}, {"name": "Шпинат", "amount": "30 г"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 350, 20.2, 16.7, 28.9, 4.9, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], null, 10, 'low'),
  ('Сирна запіканка з родзинками', 'сніданок', 'основна страва', 'Змішайте всі інгредієнти. Викладіть у форму й випікайте 30 хвилин при 180 °C.', '[{"name": "Сир кисломолочний", "amount": "200 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Манна крупа", "amount": "20 г"}, {"name": "Цукор", "amount": "1 ч. л."}, {"name": "Родзинки", "amount": "20 г"}]'::jsonb, 468, 43.5, 15.5, 41.2, 1.5, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], 'ukrainian', 40, 'low'),
  ('Сирники з бананом', 'сніданок', 'основна страва', 'Розімніть банан із сиром, додайте яйце та борошно. Сформуйте сирники й смажте по 3 хвилини з кожного боку.', '[{"name": "Сир кисломолочний", "amount": "150 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Банан", "amount": "0.5 шт"}, {"name": "Борошно", "amount": "20 г"}]'::jsonb, 382, 35.1, 13.1, 33.1, 2.2, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], 'ukrainian', 20, 'low'),
  ('Грецький йогурт з гранолою і бананом', 'сніданок', 'десерт', 'Викладіть йогурт у миску. Додайте нарізаний банан і гранолу.', '[{"name": "Грецький йогурт", "amount": "200 г"}, {"name": "Гранола", "amount": "30 г"}, {"name": "Банан", "amount": "1 шт"}]'::jsonb, 436, 22.3, 15.8, 53.6, 5.2, 'vegetarian', array['gluten', 'lactose']::text[], null, 5, 'low'),
  ('Смузі-боул з ягодами', 'сніданок', 'десерт', 'Збийте ягоди, банан і йогурт блендером. Перелийте в миску та посипте гранолою й чіа.', '[{"name": "Ягоди", "amount": "100 г"}, {"name": "Банан", "amount": "1 шт"}, {"name": "Йогурт натуральний", "amount": "100 г"}, {"name": "Гранола", "amount": "20 г"}, {"name": "Насіння чіа", "amount": "5 г"}]'::jsonb, 326, 9.0, 8.8, 56.2, 9.2, 'vegetarian', array['berries', 'gluten', 'lactose']::text[], null, 10, 'low'),
  ('Зелене смузі з ківі', 'сніданок', 'напій', 'Збийте всі інгредієнти блендером до однорідності.', '[{"name": "Шпинат", "amount": "40 г"}, {"name": "Ківі", "amount": "2 шт"}, {"name": "Банан", "amount": "1 шт"}, {"name": "Вода", "amount": "150 мл"}]'::jsonb, 208, 4.1, 1.3, 51.5, 8.5, 'vegan', '{}'::text[], null, 5, 'low'),
  ('Бутерброд з сиром і огірком', 'сніданок', 'закуска', 'Намастіть хліб вершковим сиром. Викладіть шматочки огірка й посипте зеленню.', '[{"name": "Цільнозерновий хліб", "amount": "2 скибки"}, {"name": "Вершковий сир", "amount": "30 г"}, {"name": "Огірок", "amount": "0.5 шт"}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}]'::jsonb, 234, 7.7, 9.4, 30.3, 4.6, 'vegetarian', array['gluten', 'lactose']::text[], null, 5, 'low'),
  ('Бутерброд з тунцем', 'сніданок', 'закуска', 'Розімніть тунець із гірчицею. Намастіть на хліб і додайте огірок.', '[{"name": "Житній хліб", "amount": "2 скибки"}, {"name": "Тунець консервований", "amount": "60 г"}, {"name": "Огірок", "amount": "0.5 шт"}, {"name": "Гірчиця", "amount": "1 ч. л."}]'::jsonb, 200, 18.0, 1.6, 27.9, 4.0, 'pescatarian', array['fish', 'gluten', 'mustard']::text[], null, 10, 'low'),
  ('Сендвіч з індичкою та овочами', 'сніданок', 'закуска', 'Намастіть хліб гірчицею. Викладіть індичку, салат і помідор та накрийте другою скибкою.', '[{"name": "Цільнозерновий хліб", "amount": "2 скибки"}, {"name": "Філе індички", "amount": "60 г"}, {"name": "Листя салату", "amount": "20 г"}, {"name": "Помідор", "amount": "0.5 шт"}, {"name": "Гірчиця", "amount": "1 ч. л."}]'::jsonb, 234, 19.5, 3.6, 29.8, 5.2, 'any', array['gluten', 'mustard', 'tomatoes']::text[], null, 10, 'low'),
  ('Оладки на кефірі', 'сніданок', 'випічка', 'Змішайте борошно, кефір, яйце та цукор. Смажте оладки по 2 хвилини з кожного боку.', '[{"name": "Борошно", "amount": "80 г"}, {"name": "Кефір", "amount": "100 мл"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Цукор", "amount": "1 ч. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 464, 17.9, 13.5, 67.0, 2.4, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], 'ukrainian', 25, 'low'),
  ('Млинці з сиром', 'сніданок', 'випічка', 'Замісіть рідке тісто й посмажте тонкі млинці. Змішайте сир із цукром і загорніть у млинці.', '[{"name": "Борошно", "amount": "50 г"}, {"name": "Молоко", "amount": "120 мл"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Сир кисломолочний", "amount": "100 г"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Цукор", "amount": "1 ч. л."}]'::jsonb, 496, 32.4, 18.7, 50.0, 1.5, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], 'ukrainian', 30, 'low'),
  ('Бананові млинці з вівса', 'сніданок', 'випічка', 'Збийте всі інгредієнти блендером. Смажте невеликі млинці по 2 хвилини з кожного боку.', '[{"name": "Вівсяні пластівці", "amount": "40 г"}, {"name": "Банан", "amount": "1 шт"}, {"name": "Яйце", "amount": "1 шт"}]'::jsonb, 333, 13.4, 8.4, 52.0, 7.1, 'vegetarian', array['eggs', 'gluten']::text[], null, 15, 'low'),
  ('Тост з арахісовою пастою та бананом', 'сніданок', 'закуска', 'Підсушіть хліб. Намастіть арахісовою пастою й викладіть кружальця банана.', '[{"name": "Цільнозерновий хліб", "amount": "2 скибки"}, {"name": "Арахісова паста", "amount": "2 ст. л."}, {"name": "Банан", "amount": "1 шт"}]'::jsonb, 434, 14.2, 17.5, 59.1, 9.1, 'vegan', array['gluten', 'peanuts']::text[], null, 5, 'low'),
  ('Мюслі з молоком і яблуком', 'сніданок', 'основна страва', 'Залийте гранолу молоком. Додайте нарізане яблуко.', '[{"name": "Гранола", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Яблуко", "amount": "0.5 шт"}]'::jsonb, 342, 9.6, 12.9, 47.5, 5.3, 'vegetarian', array['gluten', 'lactose']::text[], null, 5, 'low'),
  ('Вівсяна запіканка з яблуком', 'сніданок', 'випічка', 'Змішайте пластівці, яйце, молоко та мед. Додайте нарізане яблуко й випікайте 25 хвилин при 180 °C.', '[{"name": "Вівсяні пластівці", "amount": "60 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Молоко", "amount": "100 мл"}, {"name": "Яблуко", "amount": "1 шт"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 452, 18.1, 12.2, 67.8, 9.6, 'vegetarian', array['eggs', 'gluten', 'honey', 'lactose']::text[], null, 30, 'low'),
  ('Кіноа з ягодами і мигдалем', 'сніданок', 'основна страва', 'Відваріть кіноа в молоці до м’якості. Додайте ягоди та подрібнений мигдаль.', '[{"name": "Кіноа", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Ягоди", "amount": "60 г"}, {"name": "Мигдаль", "amount": "10 г"}]'::jsonb, 350, 13.9, 11.9, 46.0, 6.5, 'vegetarian', array['berries', 'lactose', 'nuts']::text[], null, 20, 'medium'),
  ('Лаваш з яйцем і сиром', 'сніданок', 'основна страва', 'Зробіть омлет із яєць і сиру. Загорніть у лаваш із нарізаним помідором.', '[{"name": "Лаваш", "amount": "1 шт"}, {"name": "Яйце", "amount": "2 шт"}, {"name": "Твердий сир", "amount": "20 г"}, {"name": "Помідор", "amount": "0.5 шт"}]'::jsonb, 401, 24.7, 16.6, 36.9, 2.1, 'vegetarian', array['eggs', 'gluten', 'lactose', 'tomatoes']::text[], 'georgian', 10, 'low'),
  ('Суп-пюре з броколі', 'обід', 'суп', 'Відваріть броколі, картоплю й цибулю в бульйоні. Збийте блендером і додайте вершки.', '[{"name": "Броколі", "amount": "200 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Вершки 10%", "amount": "50 мл"}, {"name": "Овочевий бульйон", "amount": "250 мл"}]'::jsonb, 232, 10.3, 6.2, 38.6, 8.1, 'vegetarian', array['lactose']::text[], null, 25, 'low'),
  ('Суп з сочевиці', 'обід', 'суп', 'Обсмажте цибулю з морквою й томатною пастою. Додайте сочевицю з водою та варіть 20 хвилин.', '[{"name": "Сочевиця", "amount": "50 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Томатна паста", "amount": "1 ст. л."}, {"name": "Вода", "amount": "300 мл"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 265, 14.3, 5.8, 41.0, 9.0, 'vegan', array['legumes', 'tomatoes']::text[], null, 30, 'low'),
  ('Томатний суп з вершками', 'обід', 'суп', 'Обсмажте цибулю з часником. Додайте томати та бульйон і варіть 15 хвилин. Збийте блендером і додайте вершки.', '[{"name": "Томати в соку", "amount": "250 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Вершки 10%", "amount": "30 мл"}, {"name": "Овочевий бульйон", "amount": "150 мл"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 169, 5.0, 8.7, 19.8, 4.5, 'vegetarian', array['lactose', 'tomatoes']::text[], 'mediterranean', 25, 'low'),
  ('Грибний суп', 'обід', 'суп', 'Обсмажте гриби з цибулею й морквою. Додайте картоплю з водою та варіть 20 хвилин. Подавайте зі сметаною.', '[{"name": "Печериці", "amount": "150 г"}, {"name": "Картопля", "amount": "1.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Сметана 15%", "amount": "20 г"}, {"name": "Вода", "amount": "300 мл"}]'::jsonb, 213, 9.0, 3.7, 38.6, 6.6, 'vegetarian', array['lactose', 'mushrooms']::text[], 'ukrainian', 30, 'low'),
  ('Суп харчо', 'обід', 'суп', 'Зваріть яловичину до м’якості. Додайте рис, цибулю й томатну пасту та варіть 15 хвилин. Наприкінці додайте товчені горіхи та часник.', '[{"name": "Яловичина пісна", "amount": "80 г"}, {"name": "Рис", "amount": "25 г"}, {"name": "Томатна паста", "amount": "1 ст. л."}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Волоські горіхи", "amount": "10 г"}, {"name": "Вода", "amount": "300 мл"}]'::jsonb, 350, 21.0, 16.4, 32.0, 3.0, 'any', array['nuts', 'tomatoes']::text[], 'georgian', 50, 'medium'),
  ('Суп з фрикадельками', 'обід', 'суп', 'Скачайте з фаршу фрикадельки. Опустіть їх у киплячу воду з картоплею, морквою та цибулею. Наприкінці додайте вермішель.', '[{"name": "Курячий фарш", "amount": "100 г"}, {"name": "Картопля", "amount": "1.5 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Макарони", "amount": "20 г"}, {"name": "Вода", "amount": "300 мл"}]'::jsonb, 361, 23.2, 8.6, 47.5, 5.7, 'any', array['gluten']::text[], 'ukrainian', 35, 'low'),
  ('Рибна юшка', 'обід', 'суп', 'Відваріть овочі 15 хвилин. Додайте шматки риби й варіть ще 10 хвилин. Посипте зеленню.', '[{"name": "Філе білої риби", "amount": "150 г"}, {"name": "Картопля", "amount": "1.5 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}, {"name": "Вода", "amount": "350 мл"}]'::jsonb, 270, 29.4, 1.5, 33.4, 5.3, 'pescatarian', array['fish']::text[], 'ukrainian', 35, 'low'),
  ('Щі зі свіжої капусти', 'обід', 'суп', 'Зваріть бульйон зі свининою. Додайте картоплю, а за 10 хвилин капусту та засмажку з цибулі, моркви й томатної пасти.', '[{"name": "Капуста", "amount": "200 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Томатна паста", "amount": "1 ст. л."}, {"name": "Пісна свинина", "amount": "60 г"}, {"name": "Вода", "amount": "300 мл"}]'::jsonb, 296, 18.4, 8.9, 39.5, 9.6, 'any', array['tomatoes']::text[], 'ukrainian', 40, 'low'),
  ('Овочевий суп з вермішеллю', 'обід', 'суп', 'Відваріть нарізані овочі 15 хвилин. Додайте вермішель і варіть ще 5 хвилин.', '[{"name": "Макарони", "amount": "25 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Стручкова квасоля", "amount": "50 г"}, {"name": "Вода", "amount": "350 мл"}]'::jsonb, 229, 7.1, 0.8, 50.1, 7.6, 'vegan', array['gluten']::text[], 'ukrainian', 25, 'low'),
  ('Гарбузовий суп з імбиром і кокосовим молоком', 'обід', 'суп', 'Обсмажте цибулю з імбиром. Додайте гарбуз і воду та варіть 15 хвилин. Збийте блендером із кокосовим молоком.', '[{"name": "Гарбуз", "amount": "250 г"}, {"name": "Імбир", "amount": "5 г"}, {"name": "Кокосове молоко", "amount": "80 мл"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Вода", "amount": "200 мл"}]'::jsonb, 287, 4.6, 22.1, 23.1, 2.0, 'vegan', '{}'::text[], 'asian', 25, 'low'),
  ('Мінестроне', 'обід', 'суп', 'Обсмажте моркву із селерою. Додайте кабачок, томати, квасолю та воду й варіть 20 хвилин. Наприкінці додайте макарони.', '[{"name": "Квасоля консервована", "amount": "60 г"}, {"name": "Макарони", "amount": "25 г"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Селера", "amount": "40 г"}, {"name": "Томати в соку", "amount": "100 г"}, {"name": "Кабачок", "amount": "80 г"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Вода", "amount": "250 мл"}]'::jsonb, 252, 10.0, 6.3, 40.9, 8.4, 'vegan', array['celery', 'gluten', 'legumes', 'tomatoes']::text[], 'italian', 35, 'low'),
  ('Окрошка на кефірі', 'обід', 'суп', 'Наріжте відварені картоплю та яйце, огірок, редиску й шинку. Залийте кефіром і посипте зеленню.', '[{"name": "Кефір", "amount": "300 мл"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Шинка", "amount": "50 г"}, {"name": "Зелень (кріп, петрушка)", "amount": "15 г"}, {"name": "Редиска", "amount": "50 г"}]'::jsonb, 395, 27.9, 15.6, 36.1, 4.0, 'any', array['eggs', 'lactose']::text[], 'ukrainian', 20, 'low'),
  ('Рисовий суп з куркою', 'обід', 'суп', 'Зваріть курку з овочами 15 хвилин. Додайте рис і варіть ще 10 хвилин.', '[{"name": "Куряче філе", "amount": "80 г"}, {"name": "Рис", "amount": "30 г"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Вода", "amount": "350 мл"}]'::jsonb, 299, 23.3, 1.9, 47.7, 4.4, 'any', '{}'::text[], null, 30, 'low'),
  ('Куряча грудка з булгуром і овочами', 'обід', 'основна страва', 'Відваріть булгур. Обсмажте нарізані курку, перець і цибулю до готовності та змішайте з крупою.', '[{"name": "Куряче філе", "amount": "130 г"}, {"name": "Булгур", "amount": "70 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 474, 39.9, 8.7, 64.0, 11.5, 'any', array['gluten']::text[], null, 30, 'low'),
  ('Гречка з грибами і цибулею', 'обід', 'основна страва', 'Відваріть гречку. Обсмажте гриби з цибулею 10 хвилин і додайте до крупи.', '[{"name": "Гречка", "amount": "80 г"}, {"name": "Печериці", "amount": "150 г"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 381, 15.6, 8.2, 61.8, 10.9, 'vegan', array['mushrooms']::text[], 'ukrainian', 30, 'low'),
  ('Смажений рис з яйцем і овочами', 'обід', 'основна страва', 'Відваріть рис. Обсмажте моркву з горошком, додайте рис і яйце та заправте соєвим соусом.', '[{"name": "Рис", "amount": "70 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Зелений горошок", "amount": "40 г"}, {"name": "Соєвий соус", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 419, 15.4, 10.9, 64.8, 4.2, 'vegetarian', array['eggs', 'gluten', 'legumes', 'soy']::text[], 'asian', 25, 'low'),
  ('Паста з тунцем і томатами', 'обід', 'основна страва', 'Відваріть макарони. Прогрійте томати з часником і тунцем 7 хвилин і змішайте з пастою.', '[{"name": "Макарони", "amount": "80 г"}, {"name": "Тунець консервований", "amount": "80 г"}, {"name": "Томати в соку", "amount": "120 г"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 439, 29.7, 7.3, 64.9, 4.3, 'pescatarian', array['fish', 'gluten', 'tomatoes']::text[], 'italian', 20, 'low'),
  ('Паста з овочами і пармезаном', 'обід', 'основна страва', 'Відваріть макарони. Обсмажте кабачок із часником і помідором. Змішайте з пастою та посипте пармезаном.', '[{"name": "Макарони", "amount": "80 г"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Пармезан", "amount": "15 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 425, 17.4, 10.9, 65.9, 4.7, 'vegetarian', array['gluten', 'lactose', 'tomatoes']::text[], 'italian', 25, 'medium'),
  ('Паста з яйцем і шинкою', 'обід', 'основна страва', 'Відваріть макарони. Обсмажте шинку. Змішайте гарячу пасту зі збитим яйцем, шинкою та сиром.', '[{"name": "Макарони", "amount": "80 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Шинка", "amount": "40 г"}, {"name": "Пармезан", "amount": "15 г"}]'::jsonb, 467, 28.7, 12.6, 58.4, 2.4, 'any', array['eggs', 'gluten', 'lactose']::text[], 'italian', 20, 'medium'),
  ('Плов з нутом і морквою', 'обід', 'основна страва', 'Обсмажте цибулю з морквою. Додайте нут, рис і воду та тушкуйте під кришкою 25 хвилин.', '[{"name": "Рис", "amount": "80 г"}, {"name": "Морква", "amount": "1.5 шт"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Нут консервований", "amount": "60 г"}, {"name": "Олія", "amount": "2 ч. л."}]'::jsonb, 514, 11.8, 12.3, 92.2, 9.4, 'vegan', array['legumes']::text[], 'asian', 40, 'low'),
  ('Курка в соєвому соусі з рисом', 'обід', 'основна страва', 'Відваріть рис. Обсмажте курку з часником, додайте соєвий соус і броколі та тушкуйте 7 хвилин.', '[{"name": "Куряче філе", "amount": "130 г"}, {"name": "Рис", "amount": "70 г"}, {"name": "Соєвий соус", "amount": "1 ст. л."}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Броколі", "amount": "80 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 467, 38.5, 8.2, 61.7, 3.2, 'any', array['gluten', 'soy']::text[], 'asian', 30, 'low'),
  ('Локшина з тофу та овочами', 'обід', 'основна страва', 'Замочіть локшину в гарячій воді. Обсмажте тофу з овочами, додайте локшину та соєвий соус.', '[{"name": "Рисова локшина", "amount": "70 г"}, {"name": "Тофу", "amount": "100 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Соєвий соус", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 430, 15.0, 10.5, 70.0, 5.0, 'vegan', array['gluten', 'soy']::text[], 'asian', 25, 'low'),
  ('Фрикадельки з рисом у томатному соусі', 'обід', 'основна страва', 'Змішайте фарш, яйце та цибулю й скачайте фрикадельки. Тушкуйте їх у томатах 20 хвилин і подавайте з відвареним рисом.', '[{"name": "Курячий фарш", "amount": "130 г"}, {"name": "Рис", "amount": "60 г"}, {"name": "Яйце", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Томати в соку", "amount": "100 г"}]'::jsonb, 469, 31.4, 13.6, 55.0, 3.0, 'any', array['eggs', 'tomatoes']::text[], null, 40, 'low'),
  ('Курячі котлети з картопляним пюре', 'обід', 'основна страва', 'Сформуйте котлети з фаршу, яйця й цибулі та запечіть 25 хвилин. Відваріть картоплю й розімніть із молоком і маслом.', '[{"name": "Курячий фарш", "amount": "130 г"}, {"name": "Яйце", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Картопля", "amount": "3 шт"}, {"name": "Молоко", "amount": "40 мл"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 529, 33.2, 18.4, 56.7, 7.3, 'any', array['eggs', 'lactose']::text[], 'ukrainian', 45, 'low'),
  ('Ліниві голубці', 'обід', 'основна страва', 'Змішайте дрібно нашатковану капусту з фаршем, рисом і цибулею. Сформуйте котлети й тушкуйте 30 хвилин. Подавайте зі сметаною.', '[{"name": "Капуста", "amount": "150 г"}, {"name": "Курячий фарш", "amount": "100 г"}, {"name": "Рис", "amount": "30 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Сметана 15%", "amount": "30 г"}]'::jsonb, 350, 23.0, 12.9, 36.6, 4.8, 'any', array['lactose']::text[], 'ukrainian', 45, 'low'),
  ('Курячі стегна з картоплею в духовці', 'обід', 'основна страва', 'Викладіть стегна й картоплю на деко зі спеціями та часником. Запікайте 40 хвилин при 200 °C.', '[{"name": "Куряче стегно без шкіри", "amount": "170 г"}, {"name": "Картопля", "amount": "3 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Спеції", "amount": "1 ч. л."}]'::jsonb, 558, 40.5, 20.7, 53.3, 7.1, 'any', '{}'::text[], null, 50, 'low'),
  ('Яловичина тушкована з овочами', 'обід', 'основна страва', 'Обсмажте яловичину. Додайте овочі, томатну пасту й воду та тушкуйте під кришкою 50 хвилин.', '[{"name": "Яловичина пісна", "amount": "130 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Картопля", "amount": "2 шт"}, {"name": "Томатна паста", "amount": "1 ст. л."}]'::jsonb, 474, 32.2, 16.1, 52.1, 8.6, 'any', array['tomatoes']::text[], 'ukrainian', 70, 'medium'),
  ('Чечевичне рагу', 'обід', 'основна страва', 'Обсмажте цибулю з морквою й томатною пастою. Додайте сочевицю з водою та тушкуйте 25 хвилин.', '[{"name": "Сочевиця", "amount": "70 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Томатна паста", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 345, 19.7, 6.0, 55.2, 11.9, 'vegan', array['legumes', 'tomatoes']::text[], null, 35, 'low'),
  ('Нут з овочами в томатному соусі', 'обід', 'основна страва', 'Обсмажте цибулю з часником. Додайте томати й нут і тушкуйте 10 хвилин. Наприкінці додайте шпинат.', '[{"name": "Нут консервований", "amount": "150 г"}, {"name": "Томати в соку", "amount": "150 г"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Шпинат", "amount": "50 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 310, 14.9, 9.3, 46.3, 13.8, 'vegan', array['legumes', 'tomatoes']::text[], 'mediterranean', 25, 'low'),
  ('Ризото з грибами', 'обід', 'основна страва', 'Обсмажте цибулю з грибами. Додайте рис і поступово підливайте гарячий бульйон 20 хвилин. Наприкінці додайте сир і масло.', '[{"name": "Рис", "amount": "75 г"}, {"name": "Печериці", "amount": "120 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Пармезан", "amount": "15 г"}, {"name": "Овочевий бульйон", "amount": "250 мл"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 406, 15.6, 9.4, 67.3, 2.9, 'vegetarian', array['lactose', 'mushrooms']::text[], 'italian', 35, 'medium'),
  ('Креветки з кускусом', 'обід', 'основна страва', 'Залийте кускус окропом. Обсмажте креветки з часником і помідором. Змішайте та збризніть лимонним соком.', '[{"name": "Креветки", "amount": "130 г"}, {"name": "Кускус", "amount": "60 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Лимонний сік", "amount": "1 ч. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 396, 32.4, 6.9, 49.4, 4.3, 'pescatarian', array['citrus', 'gluten', 'seafood', 'tomatoes']::text[], 'mediterranean', 20, 'medium'),
  ('Лосось з рисом і броколі', 'обід', 'основна страва', 'Відваріть рис. Запікайте лосось 15 хвилин при 190 °C. Броколі приготуйте на пару та збризніть лимонним соком.', '[{"name": "Лосось", "amount": "140 г"}, {"name": "Рис", "amount": "60 г"}, {"name": "Броколі", "amount": "100 г"}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 519, 35.0, 19.0, 53.5, 3.4, 'pescatarian', array['citrus', 'fish']::text[], null, 30, 'medium'),
  ('Курячий шашлик з овочами', 'обід', 'основна страва', 'Наріжте курку та овочі, нанижте на шпажки. Запікайте 25 хвилин при 200 °C.', '[{"name": "Куряче філе", "amount": "150 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 275, 37.3, 8.4, 13.9, 4.1, 'any', '{}'::text[], 'georgian', 40, 'low'),
  ('Грецький салат', 'обід', 'салат', 'Наріжте овочі великими шматками. Додайте бринзу та заправте олією.', '[{"name": "Помідор", "amount": "2 шт"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Солодкий перець", "amount": "0.5 шт"}, {"name": "Бринза", "amount": "50 г"}, {"name": "Олія", "amount": "2 ч. л."}, {"name": "Цибуля", "amount": "0.25 шт"}]'::jsonb, 296, 10.3, 21.1, 18.8, 4.4, 'vegetarian', array['lactose', 'tomatoes']::text[], 'mediterranean', 10, 'low'),
  ('Салат з куркою та авокадо', 'обід', 'салат', 'Відваріть і наріжте курку. Змішайте з салатом, авокадо та помідором і заправте олією з лимонним соком.', '[{"name": "Куряче філе", "amount": "100 г"}, {"name": "Авокадо", "amount": "0.5 шт"}, {"name": "Листя салату", "amount": "50 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Лимонний сік", "amount": "1 ч. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 301, 26.1, 18.5, 12.4, 6.9, 'any', array['citrus', 'tomatoes']::text[], null, 15, 'medium'),
  ('Салат з нутом і овочами', 'обід', 'салат', 'Змішайте нут із нарізаними овочами. Заправте олією та лимонним соком.', '[{"name": "Нут консервований", "amount": "100 г"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.25 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 206, 8.8, 7.8, 28.6, 8.1, 'vegan', array['citrus', 'legumes', 'tomatoes']::text[], 'mediterranean', 10, 'low'),
  ('Салат з буряка з горіхами', 'обід', 'салат', 'Відварений буряк натріть на тертці. Додайте товчені горіхи, часник і сметану.', '[{"name": "Буряк", "amount": "1.5 шт"}, {"name": "Волоські горіхи", "amount": "15 г"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Сметана 15%", "amount": "20 г"}]'::jsonb, 232, 6.6, 13.2, 26.5, 7.4, 'vegetarian', array['lactose', 'nuts']::text[], 'ukrainian', 15, 'medium'),
  ('Салат з тунцем і квасолею', 'обід', 'салат', 'Змішайте тунець, квасолю, нарізані цибулю та помідор. Заправте олією.', '[{"name": "Тунець консервований", "amount": "80 г"}, {"name": "Квасоля консервована", "amount": "80 г"}, {"name": "Цибуля", "amount": "0.25 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 230, 25.1, 6.4, 19.3, 6.3, 'pescatarian', array['fish', 'legumes', 'tomatoes']::text[], 'mediterranean', 10, 'low'),
  ('Капустяний салат з морквою', 'обід', 'салат', 'Нашаткуйте капусту й посоліть, пом’яніть руками. Додайте натерту моркву, зелень, олію та лимонний сік.', '[{"name": "Капуста", "amount": "150 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}]'::jsonb, 121, 3.6, 5.4, 17.6, 6.2, 'vegan', array['citrus']::text[], 'ukrainian', 10, 'low'),
  ('Теплий салат з індичкою і руколою', 'обід', 'салат', 'Обсмажте нарізану індичку 8 хвилин. Викладіть на руколу з помідором і посипте пармезаном.', '[{"name": "Філе індички", "amount": "100 г"}, {"name": "Руккола", "amount": "40 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Пармезан", "amount": "10 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 227, 27.5, 10.3, 5.4, 1.8, 'any', array['lactose', 'tomatoes']::text[], 'italian', 20, 'medium'),
  ('Рис із зеленню', 'обід', 'гарнір', 'Відваріть рис до готовності. Додайте масло та дрібно нарізану зелень.', '[{"name": "Рис", "amount": "70 г"}, {"name": "Зелень (кріп, петрушка)", "amount": "10 г"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 278, 5.2, 4.5, 54.5, 1.2, 'vegetarian', array['lactose']::text[], null, 20, 'low'),
  ('Гречка розсипчаста', 'обід', 'гарнір', 'Залийте гречку подвійною кількістю води й варіть 15 хвилин. Додайте масло.', '[{"name": "Гречка", "amount": "80 г"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 308, 10.1, 6.7, 49.6, 8.0, 'vegetarian', array['lactose']::text[], 'ukrainian', 20, 'low'),
  ('Булгур з овочами', 'обід', 'гарнір', 'Обсмажте дрібно нарізані овочі. Додайте булгур і воду й варіть 15 хвилин.', '[{"name": "Булгур", "amount": "70 г"}, {"name": "Морква", "amount": "0.5 шт"}, {"name": "Солодкий перець", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 315, 9.4, 6.1, 60.8, 10.7, 'vegan', array['gluten']::text[], null, 25, 'low'),
  ('Запечена картопля з травами', 'обід', 'гарнір', 'Наріжте картоплю часточками, змішайте зі спеціями, часником і олією. Запікайте 35 хвилин при 200 °C.', '[{"name": "Картопля", "amount": "3 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Спеції", "amount": "1 ч. л."}, {"name": "Часник", "amount": "1 зубчик"}]'::jsonb, 286, 6.5, 5.4, 53.3, 7.1, 'vegan', '{}'::text[], null, 40, 'low'),
  ('Запечений лосось з овочами', 'вечеря', 'основна страва', 'Викладіть рибу й овочі на деко, збризніть олією та лимонним соком. Запікайте 18 хвилин при 190 °C.', '[{"name": "Лосось", "amount": "140 г"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 360, 30.1, 23.7, 7.3, 2.2, 'pescatarian', array['citrus', 'fish', 'tomatoes']::text[], 'mediterranean', 25, 'medium'),
  ('Хек у сметані', 'вечеря', 'основна страва', 'Викладіть рибу на цибулю з морквою. Залийте сметаною й тушкуйте під кришкою 20 хвилин.', '[{"name": "Філе білої риби", "amount": "180 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Сметана 15%", "amount": "40 г"}, {"name": "Морква", "amount": "0.5 шт"}]'::jsonb, 240, 32.4, 7.6, 8.8, 1.8, 'pescatarian', array['fish', 'lactose']::text[], 'ukrainian', 30, 'low'),
  ('Риба на пару з броколі', 'вечеря', 'основна страва', 'Готуйте рибу й броколі на пару 15 хвилин. Збризніть лимонним соком.', '[{"name": "Філе білої риби", "amount": "180 г"}, {"name": "Броколі", "amount": "150 г"}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 196, 34.8, 2.0, 10.8, 3.9, 'pescatarian', array['citrus', 'fish']::text[], null, 20, 'low'),
  ('Тунцеві котлети', 'вечеря', 'основна страва', 'Розімніть тунець із відвареною картоплею, яйцем і цибулею. Сформуйте котлети, обваляйте в сухарях і смажте по 3 хвилини з кожного боку.', '[{"name": "Тунець консервований", "amount": "120 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Яйце", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Сухарі панірувальні", "amount": "15 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 349, 35.3, 9.7, 31.3, 3.5, 'pescatarian', array['eggs', 'fish', 'gluten']::text[], null, 25, 'low'),
  ('Креветки з часником і кабачком', 'вечеря', 'основна страва', 'Обсмажте кабачок 4 хвилини. Додайте креветки з часником і готуйте ще 4 хвилини. Збризніть лимонним соком.', '[{"name": "Креветки", "amount": "150 г"}, {"name": "Кабачок", "amount": "120 г"}, {"name": "Часник", "amount": "2 зубчики"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 205, 29.0, 6.9, 6.7, 1.4, 'pescatarian', array['citrus', 'seafood']::text[], null, 15, 'medium'),
  ('Курка запечена з моцарелою і помідорами', 'вечеря', 'основна страва', 'Викладіть курку на деко, накрийте шматочками помідора й сиром. Запікайте 25 хвилин при 190 °C.', '[{"name": "Куряче філе", "amount": "160 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Моцарела", "amount": "40 г"}]'::jsonb, 294, 44.9, 10.8, 4.7, 1.2, 'any', array['lactose', 'tomatoes']::text[], 'italian', 30, 'low'),
  ('Курка по-грецьки з овочами', 'вечеря', 'основна страва', 'Обсмажте курку з овочами 15 хвилин. Додайте бринзу й тушкуйте ще 8 хвилин.', '[{"name": "Куряче філе", "amount": "150 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Бринза", "amount": "30 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 355, 41.2, 14.6, 15.9, 4.3, 'any', array['lactose', 'tomatoes']::text[], 'mediterranean', 35, 'low'),
  ('Курячі тефтелі в томатному соусі', 'вечеря', 'основна страва', 'Змішайте фарш, відварений рис, яйце та цибулю. Скачайте тефтелі й тушкуйте в томатах 20 хвилин.', '[{"name": "Курячий фарш", "amount": "150 г"}, {"name": "Томати в соку", "amount": "150 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Яйце", "amount": "0.5 шт"}, {"name": "Рис", "amount": "25 г"}]'::jsonb, 391, 33.0, 15.1, 30.5, 3.3, 'any', array['eggs', 'tomatoes']::text[], null, 35, 'low'),
  ('Індичка тушкована з овочами', 'вечеря', 'основна страва', 'Обсмажте індичку. Додайте овочі та трохи води й тушкуйте під кришкою 20 хвилин.', '[{"name": "Філе індички", "amount": "150 г"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 282, 35.4, 8.5, 14.7, 3.9, 'any', '{}'::text[], null, 35, 'low'),
  ('Овочева запіканка із сиром', 'вечеря', 'основна страва', 'Наріжте овочі й викладіть у форму. Залийте збитим яйцем, посипте сиром і запікайте 30 хвилин при 190 °C.', '[{"name": "Цвітна капуста", "amount": "150 г"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Твердий сир", "amount": "30 г"}]'::jsonb, 238, 18.5, 14.1, 11.0, 4.0, 'vegetarian', array['eggs', 'lactose']::text[], null, 40, 'low'),
  ('Баклажани з помідорами і моцарелою', 'вечеря', 'основна страва', 'Викладіть шари баклажанів і помідорів з часником. Посипте сиром і запікайте 25 хвилин при 190 °C.', '[{"name": "Баклажан", "amount": "200 г"}, {"name": "Помідор", "amount": "2 шт"}, {"name": "Моцарела", "amount": "40 г"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 236, 11.3, 13.4, 21.9, 8.5, 'vegetarian', array['lactose', 'tomatoes']::text[], 'italian', 35, 'low'),
  ('Фаршировані кабачки', 'вечеря', 'основна страва', 'Видаліть серцевину кабачків і наповніть сумішшю фаршу, рису та цибулі. Тушкуйте в томатах 35 хвилин.', '[{"name": "Кабачок", "amount": "250 г"}, {"name": "Курячий фарш", "amount": "80 г"}, {"name": "Рис", "amount": "25 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Томати в соку", "amount": "80 г"}]'::jsonb, 277, 19.8, 7.5, 34.6, 4.7, 'any', array['tomatoes']::text[], 'ukrainian', 50, 'low'),
  ('Омлет з грибами', 'вечеря', 'основна страва', 'Обсмажте гриби 5 хвилин. Залийте збитими яйцями, посипте сиром і готуйте під кришкою 5 хвилин.', '[{"name": "Яйце", "amount": "3 шт"}, {"name": "Печериці", "amount": "100 г"}, {"name": "Твердий сир", "amount": "20 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 372, 28.9, 26.4, 4.5, 1.0, 'vegetarian', array['eggs', 'lactose', 'mushrooms']::text[], null, 15, 'low'),
  ('Тофу з овочами в соєвому соусі', 'вечеря', 'основна страва', 'Обсмажте тофу до золотистої скоринки. Додайте овочі й соєвий соус та готуйте ще 6 хвилин.', '[{"name": "Тофу", "amount": "150 г"}, {"name": "Броколі", "amount": "100 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Соєвий соус", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 234, 17.2, 12.8, 17.9, 5.6, 'vegan', array['gluten', 'soy']::text[], 'asian', 20, 'low'),
  ('Локшина з креветками', 'вечеря', 'основна страва', 'Замочіть локшину. Обсмажте овочі з креветками, додайте локшину та соєвий соус.', '[{"name": "Рисова локшина", "amount": "60 г"}, {"name": "Креветки", "amount": "100 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Соєвий соус", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Морква", "amount": "0.5 шт"}]'::jsonb, 403, 24.4, 6.6, 60.1, 4.5, 'pescatarian', array['gluten', 'seafood', 'soy']::text[], 'asian', 20, 'medium'),
  ('Гречка з овочами та яйцем', 'вечеря', 'основна страва', 'Відваріть гречку. Обсмажте овочі, змішайте з крупою та подавайте з відвареним яйцем.', '[{"name": "Гречка", "amount": "60 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Солодкий перець", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 360, 16.3, 12.6, 44.3, 8.2, 'vegetarian', array['eggs']::text[], null, 25, 'low'),
