  ('Картопля з грибами у сметані', 'вечеря', 'основна страва', 'Обсмажте гриби з цибулею. Додайте нарізану картоплю й сметану та тушкуйте 20 хвилин.', '[{"name": "Картопля", "amount": "3 шт"}, {"name": "Печериці", "amount": "150 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Сметана 15%", "amount": "40 г"}]'::jsonb, 344, 12.1, 6.8, 60.8, 8.8, 'vegetarian', array['lactose', 'mushrooms']::text[], 'ukrainian', 35, 'low'),
