  ('Свинячі медальйони з салатом', 'вечеря', 'основна страва', 'Обсмажте медальйони по 5 хвилин з кожного боку. Подавайте з салатом і помідором.', '[{"name": "Пісна свинина", "amount": "130 г"}, {"name": "Листя салату", "amount": "50 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 330, 26.3, 23.5, 5.3, 1.9, 'any', array['tomatoes']::text[], null, 25, 'low'),
  ('Паста з куркою та шпинатом', 'вечеря', 'основна страва', 'Відваріть макарони. Обсмажте курку з часником, додайте шпинат і вершки та змішайте з пастою.', '[{"name": "Макарони", "amount": "75 г"}, {"name": "Куряче філе", "amount": "100 г"}, {"name": "Шпинат", "amount": "60 г"}, {"name": "Вершки 10%", "amount": "40 мл"}, {"name": "Часник", "amount": "1 зубчик"}]'::jsonb, 439, 35.2, 7.3, 59.1, 3.7, 'any', array['gluten', 'lactose']::text[], 'italian', 25, 'low'),
