  ('Салат з креветками та авокадо', 'вечеря', 'салат', 'Відваріть креветки 3 хвилини. Змішайте з овочами й авокадо та заправте олією з лимонним соком.', '[{"name": "Креветки", "amount": "100 г"}, {"name": "Авокадо", "amount": "0.5 шт"}, {"name": "Листя салату", "amount": "50 г"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Лимонний сік", "amount": "1 ч. л."}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 273, 20.9, 17.5, 12.1, 6.2, 'pescatarian', array['citrus', 'seafood']::text[], null, 15, 'medium'),
  ('Салат з печеними овочами і бринзою', 'вечеря', 'салат', 'Запечіть овочі 20 хвилин при 200 °C. Змішайте з бринзою та олією.', '[{"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Баклажан", "amount": "80 г"}, {"name": "Бринза", "amount": "30 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 193, 7.4, 12.0, 16.3, 5.8, 'vegetarian', array['lactose']::text[], 'mediterranean', 30, 'low'),
  ('Салат з сочевицею та овочами', 'вечеря', 'салат', 'Відваріть сочевицю й остудіть. Змішайте з овочами та зеленню й заправте олією з лимонним соком.', '[{"name": "Сочевиця", "amount": "40 г"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Зелень (кріп, петрушка)", "amount": "10 г"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 210, 11.9, 5.8, 29.6, 6.4, 'vegan', array['citrus', 'legumes', 'tomatoes']::text[], null, 25, 'low'),
  ('Салат з яйцем та шпинатом', 'вечеря', 'салат', 'Зваріть яйця круто. Змішайте шпинат, овочі та нарізані яйця й заправте олією.', '[{"name": "Шпинат", "amount": "60 г"}, {"name": "Яйце", "amount": "2 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Огірок", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 241, 16.9, 15.9, 8.6, 2.8, 'vegetarian', array['eggs', 'tomatoes']::text[], null, 15, 'low'),
  ('Салат з огірків і редиски', 'вечеря', 'салат', 'Наріжте овочі кружальцями. Додайте зелень і сметану.', '[{"name": "Огірок", "amount": "2 шт"}, {"name": "Редиска", "amount": "80 г"}, {"name": "Зелень (кріп, петрушка)", "amount": "10 г"}, {"name": "Сметана 15%", "amount": "30 г"}]'::jsonb, 95, 3.0, 4.9, 11.4, 2.6, 'vegetarian', array['lactose']::text[], 'ukrainian', 10, 'low'),
  ('Броколі на пару з часником', 'вечеря', 'гарнір', 'Готуйте броколі на пару 7 хвилин. Змішайте з часником, олією та лимонним соком.', '[{"name": "Броколі", "amount": "200 г"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 119, 5.9, 5.8, 15.7, 5.3, 'vegan', array['citrus']::text[], null, 10, 'low'),
  ('Печені овочі', 'вечеря', 'гарнір', 'Наріжте овочі великими шматками, змішайте з олією та запікайте 30 хвилин при 200 °C.', '[{"name": "Кабачок", "amount": "150 г"}, {"name": "Солодкий перець", "amount": "1 шт"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Баклажан", "amount": "80 г"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 155, 4.5, 6.0, 24.7, 8.5, 'vegan', '{}'::text[], null, 35, 'low'),
  ('Картопляне пюре', 'вечеря', 'гарнір', 'Відваріть картоплю до м’якості. Розімніть із гарячим молоком і маслом.', '[{"name": "Картопля", "amount": "3 шт"}, {"name": "Молоко", "amount": "60 мл"}, {"name": "Вершкове масло", "amount": "1 ч. л."}]'::jsonb, 298, 7.8, 5.8, 53.9, 6.6, 'vegetarian', array['lactose']::text[], 'ukrainian', 30, 'low'),
  ('Хумус з огірком і хлібцями', 'перекус', 'закуска', 'Нарізайте огірок паличками. Подавайте з хумусом і хлібом.', '[{"name": "Хумус", "amount": "80 г"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Житній хліб", "amount": "1 скибка"}]'::jsonb, 216, 8.9, 8.5, 27.7, 7.1, 'vegan', array['gluten', 'legumes', 'sesame']::text[], 'mediterranean', 5, 'low'),
  ('Яблуко з сиром', 'перекус', 'закуска', 'Наріжте яблуко часточками й подавайте з шматочками сиру.', '[{"name": "Яблуко", "amount": "1 шт"}, {"name": "Твердий сир", "amount": "30 г"}]'::jsonb, 183, 8.0, 8.4, 21.0, 3.6, 'vegetarian', array['lactose']::text[], null, 3, 'low'),
  ('Йогурт з горіхами і медом', 'перекус', 'закуска', 'Викладіть йогурт у миску. Додайте подрібнені горіхи та мед.', '[{"name": "Йогурт натуральний", "amount": "150 г"}, {"name": "Волоські горіхи", "amount": "15 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 209, 8.3, 14.2, 14.6, 1.0, 'vegetarian', array['honey', 'lactose', 'nuts']::text[], null, 3, 'medium'),
  ('Сир з огірком і зеленню', 'перекус', 'закуска', 'Змішайте сир із нарізаним огірком і дрібно порубаною зеленню.', '[{"name": "Сир кисломолочний", "amount": "150 г"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}]'::jsonb, 198, 26.3, 7.6, 8.4, 0.7, 'vegetarian', array['lactose']::text[], null, 5, 'low'),
  ('Варені яйця з овочами', 'перекус', 'закуска', 'Зваріть яйця 9 хвилин. Подавайте з нарізаними огірком і помідором.', '[{"name": "Яйце", "amount": "2 шт"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Помідор", "amount": "1 шт"}]'::jsonb, 190, 15.5, 10.7, 8.3, 1.7, 'vegetarian', array['eggs', 'tomatoes']::text[], null, 10, 'low'),
  ('Хлібці з авокадо', 'перекус', 'закуска', 'Розімніть авокадо з лимонним соком. Намастіть на хліб.', '[{"name": "Житній хліб", "amount": "2 скибки"}, {"name": "Авокадо", "amount": "0.5 шт"}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 250, 5.1, 12.0, 32.9, 8.6, 'vegan', array['citrus', 'gluten']::text[], null, 5, 'medium'),
  ('Рулетики з лаваша з сиром і зеленню', 'перекус', 'закуска', 'Намастіть лаваш сиром із зеленню. Викладіть огірок, загорніть і наріжте рулетики.', '[{"name": "Лаваш", "amount": "1 шт"}, {"name": "Сир кисломолочний", "amount": "60 г"}, {"name": "Зелень (кріп, петрушка)", "amount": "10 г"}, {"name": "Огірок", "amount": "0.5 шт"}]'::jsonb, 249, 16.2, 3.7, 38.4, 2.1, 'vegetarian', array['gluten', 'lactose']::text[], null, 10, 'low'),
  ('Мигдаль з яблуком', 'перекус', 'закуска', 'Наріжте яблуко й подавайте з горстю мигдалю.', '[{"name": "Мигдаль", "amount": "25 г"}, {"name": "Яблуко", "amount": "1 шт"}]'::jsonb, 228, 5.7, 12.8, 23.5, 6.6, 'vegan', array['nuts']::text[], null, 2, 'medium'),
  ('Овочеві палички з йогуртовим соусом', 'перекус', 'закуска', 'Наріжте овочі паличками. Змішайте йогурт із часником і зеленню та подавайте як соус.', '[{"name": "Морква", "amount": "1 шт"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Селера", "amount": "50 г"}, {"name": "Йогурт натуральний", "amount": "80 г"}, {"name": "Зелень (кріп, петрушка)", "amount": "5 г"}, {"name": "Часник", "amount": "1 зубчик"}]'::jsonb, 112, 5.4, 2.8, 18.3, 3.8, 'vegetarian', array['celery', 'lactose']::text[], null, 10, 'low'),
  ('Бутерброд з шинкою і сиром', 'перекус', 'закуска', 'Викладіть на хліб шинку, сир і помідор.', '[{"name": "Житній хліб", "amount": "2 скибки"}, {"name": "Шинка", "amount": "40 г"}, {"name": "Твердий сир", "amount": "20 г"}, {"name": "Помідор", "amount": "0.5 шт"}]'::jsonb, 256, 15.8, 8.2, 28.1, 4.2, 'any', array['gluten', 'lactose', 'tomatoes']::text[], null, 5, 'low'),
  ('Запечений нут зі спеціями', 'перекус', 'закуска', 'Обсушіть нут, змішайте з олією та спеціями. Запікайте 25 хвилин при 200 °C.', '[{"name": "Нут консервований", "amount": "100 г"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Спеції", "amount": "1 ч. л."}]'::jsonb, 169, 7.2, 7.6, 20.0, 6.4, 'vegan', array['legumes']::text[], null, 30, 'low'),
