  ('Банан з арахісовою пастою', 'перекус', 'десерт', 'Наріжте банан кружальцями. Полийте арахісовою пастою.', '[{"name": "Банан", "amount": "1 шт"}, {"name": "Арахісова паста", "amount": "1 ст. л."}]'::jsonb, 195, 5.1, 7.9, 29.9, 4.0, 'vegan', array['peanuts']::text[], null, 2, 'low'),
