  ('Чіа-пудинг з ягодами', 'перекус', 'десерт', 'Змішайте чіа з молоком і медом. Залиште в холодильнику на 4 години. Подавайте з ягодами.', '[{"name": "Насіння чіа", "amount": "25 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Ягоди", "amount": "60 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 249, 9.1, 11.7, 29.3, 10.3, 'vegetarian', array['berries', 'honey', 'lactose']::text[], null, 5, 'low'),
  ('Банановий щербет', 'перекус', 'десерт', 'Заморозьте нарізані банани. Збийте їх блендером із йогуртом.', '[{"name": "Банан", "amount": "2 шт"}, {"name": "Йогурт натуральний", "amount": "60 г"}]'::jsonb, 250, 5.0, 2.5, 57.9, 6.2, 'vegetarian', array['lactose']::text[], null, 5, 'low'),
  ('Запечена груша з медом і горіхами', 'перекус', 'десерт', 'Розріжте грушу навпіл, полийте медом і посипте горіхами. Запікайте 20 хвилин при 180 °C.', '[{"name": "Груша", "amount": "1 шт"}, {"name": "Волоські горіхи", "amount": "15 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 204, 2.9, 9.9, 30.3, 5.7, 'vegetarian', array['honey', 'nuts']::text[], null, 25, 'medium'),
  ('Шоколадний мус з авокадо', 'перекус', 'десерт', 'Збийте всі інгредієнти блендером до кремової текстури. Охолодіть.', '[{"name": "Авокадо", "amount": "1 шт"}, {"name": "Какао", "amount": "2 ч. л."}, {"name": "Мед", "amount": "2 ч. л."}]'::jsonb, 306, 5.0, 23.9, 30.8, 13.4, 'vegetarian', array['cocoa', 'honey']::text[], null, 10, 'medium'),
  ('Ягідний кисіль', 'перекус', 'десерт', 'Закип’ятіть ягоди з цукром і водою. Влийте розведений у воді крохмаль і проваріть 2 хвилини.', '[{"name": "Крохмаль", "amount": "15 г"}, {"name": "Ягоди", "amount": "100 г"}, {"name": "Цукор", "amount": "1 ч. л."}, {"name": "Вода", "amount": "200 мл"}]'::jsonb, 115, 0.8, 0.3, 27.4, 3.0, 'vegan', array['berries']::text[], 'ukrainian', 10, 'low'),
  ('Фініки з мигдалем', 'перекус', 'десерт', 'Вийміть кісточки з фініків і наповніть мигдалем.', '[{"name": "Фініки", "amount": "40 г"}, {"name": "Мигдаль", "amount": "15 г"}]'::jsonb, 202, 4.2, 7.7, 31.5, 5.0, 'vegan', array['nuts']::text[], null, 3, 'medium'),
