  ('Какао на молоці', 'перекус', 'напій', 'Розмішайте какао з цукром у гарячому молоці. Прогрійте 2 хвилини.', '[{"name": "Молоко", "amount": "250 мл"}, {"name": "Какао", "amount": "2 ч. л."}, {"name": "Цукор", "amount": "1 ч. л."}]'::jsonb, 172, 9.2, 7.7, 22.6, 3.3, 'vegetarian', array['cocoa', 'lactose']::text[], null, 7, 'low'),
