  ('Смузі з манго і йогуртом', 'перекус', 'напій', 'Збийте манго з йогуртом і водою блендером.', '[{"name": "Манго", "amount": "120 г"}, {"name": "Йогурт натуральний", "amount": "100 г"}, {"name": "Вода", "amount": "50 мл"}]'::jsonb, 132, 5.0, 3.5, 22.5, 1.9, 'vegetarian', array['lactose']::text[], null, 5, 'medium'),
  ('Імбирний чай з лимоном і медом', 'перекус', 'напій', 'Залийте імбир киплячою водою на 7 хвилин. Додайте лимон і мед.', '[{"name": "Імбир", "amount": "10 г"}, {"name": "Лимон", "amount": "0.5 шт"}, {"name": "Мед", "amount": "1 ч. л."}, {"name": "Вода", "amount": "300 мл"}]'::jsonb, 38, 0.5, 0.2, 10.2, 1.1, 'vegetarian', array['citrus', 'honey']::text[], null, 10, 'low'),
  ('Морквяно-яблучний фреш', 'перекус', 'напій', 'Віджміть сік із моркви та яблук у соковижималці.', '[{"name": "Морква", "amount": "2 шт"}, {"name": "Яблуко", "amount": "2 шт"}]'::jsonb, 222, 2.3, 0.9, 58.0, 11.7, 'vegan', '{}'::text[], null, 10, 'low'),
  ('Вівсяне печиво', 'перекус', 'випічка', 'Розімніть банан із пластівцями та родзинками. Сформуйте печиво й випікайте 15 хвилин при 180 °C.', '[{"name": "Вівсяні пластівці", "amount": "60 г"}, {"name": "Банан", "amount": "1 шт"}, {"name": "Родзинки", "amount": "15 г"}]'::jsonb, 374, 9.6, 4.6, 75.5, 9.7, 'vegan', array['gluten']::text[], null, 25, 'low'),
  ('Сирні кружальця', 'перекус', 'випічка', 'Замісіть тісто із сиру, борошна, яйця та цукру. Сформуйте кружальця й випікайте 15 хвилин при 190 °C.', '[{"name": "Сир кисломолочний", "amount": "150 г"}, {"name": "Борошно", "amount": "40 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Цукор", "amount": "1 ч. л."}]'::jsonb, 416, 36.4, 13.1, 38.7, 1.2, 'vegetarian', array['eggs', 'gluten', 'lactose']::text[], 'ukrainian', 25, 'low'),
  ('Яблучний пиріг', 'перекус', 'випічка', 'Змішайте борошно, яйце та цукор. Додайте нарізані яблука та випікайте 30 хвилин при 180 °C.', '[{"name": "Борошно", "amount": "40 г"}, {"name": "Яблуко", "amount": "2 шт"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Цукор", "amount": "2 ч. л."}]'::jsonb, 409, 11.8, 6.2, 81.2, 8.4, 'vegetarian', array['eggs', 'gluten']::text[], 'ukrainian', 40, 'low'),
